using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model   = Environment.GetEnvironmentVariable("OPENAI_MODEL")   ?? "gpt-4o-mini";
var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var researchTools = new ResearchTools();

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client
// ---------------------------------------------------------------------------
var openAiOptions = new OpenAIClientOptions();
if (baseUrl is not null)
{
    openAiOptions.Endpoint = new Uri(baseUrl);
}

IChatClient chatClient = new OpenAIClient(apiKey, openAiOptions)
    .GetChatClient(model)
    .AsIChatClient();

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research agent. When the user provides a topic, you must:
        1. Use the SearchWeb tool multiple times with different queries to gather information.
        2. Use the SaveNote tool to record key findings as you go.
        3. Use GetNotes to review everything you've collected.
        4. Provide a well-structured summary of your research to the user.
        Be thorough — search from multiple angles and save notes for each important finding.
        """,
    tools: tools);

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (.NET 10)       ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
    };

    Console.WriteLine("\n🔍 Researching...\n");

    try
    {
        var response = await agent.RunAsync(messages);

        foreach (var msg in response.Messages)
        {
            if (msg.Role == ChatRole.Assistant && msg.Text is { Length: > 0 })
            {
                Console.WriteLine(msg.Text);
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"❌ Error: {ex.Message}");
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ===========================================================================
// Tool implementations
// ===========================================================================

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new() { Timeout = TimeSpan.FromSeconds(15) };

    [Description("Search the web for information on a query. Returns a summary of search results.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up on the web.")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use Wikipedia's API for real, free, no-key-required search
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=4&format=json&utf8=1";

            var json = await _http.GetStringAsync(url);

            // Also grab a short extract for the top result
            var extractUrl = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=4&format=json&utf8=1&srprop=snippet|titlesnippet";

            return $"Search results for \"{query}\":\n{json}";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("The note content to save.")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review findings before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📋 Reviewing {_notes.Count} note(s)");

        return string.Join("\n\n", _notes.Select((n, i) => $"[Note {i + 1}] {n}"));
    }

    public void ClearNotes() => _notes.Clear();
}

