 using System.ComponentModel;
 using System.Net;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // ---------------------------------------------------------------------------
 // Configuration
 // ---------------------------------------------------------------------------
 var apiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
 var model   = Environment.GetEnvironmentVariable("OPENAI_MODEL")   ?? "gpt-4o-mini";
 var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

 // ---------------------------------------------------------------------------
 // Tools
 // ---------------------------------------------------------------------------
 var researchTools = new ResearchTools();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(researchTools.SearchWeb),
     AIFunctionFactory.Create(researchTools.SaveNote),
     AIFunctionFactory.Create(researchTools.GetNotes),
 };

 // ---------------------------------------------------------------------------
 // Chat client
 // ---------------------------------------------------------------------------
 var openAiOptions = new OpenAIClientOptions();
 if (baseUrl is not null)
 {
     openAiOptions.Endpoint = new Uri(baseUrl);
 }

 IChatClient chatClient = new OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey), openAiOptions)
     .GetChatClient(model)
     .AsIChatClient();

 // ---------------------------------------------------------------------------
 // Agent
 // ---------------------------------------------------------------------------
 var agent = new ChatClientAgent(
     chatClient,
     name: "ResearchAgent",
     description: "An AI agent that researches topics by searching the web and taking notes.",
     instructions: """
         You are a research agent. When the user provides a topic, you must:
         1. Use the SearchWeb tool multiple times with different queries to gather information.
         2. Use the SaveNote tool to record key findings as you go.
         3. Use GetNotes to review everything you've collected.
         4. Provide a well-structured summary of your research to the user.
         Be thorough — search from multiple angles and save notes for each important finding.
         """,
     tools: tools);

 // ---------------------------------------------------------------------------
 // Interactive loop
 // ---------------------------------------------------------------------------
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║        AI Research Agent (.NET 10)       ║");
 Console.WriteLine("╠══════════════════════════════════════════╣");
 Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 while (true)
 {
     Console.Write("Research topic> ");
     var topic = Console.ReadLine()?.Trim();

     if (string.IsNullOrEmpty(topic))
         continue;

     if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     researchTools.ClearNotes();

     var messages = new List<ChatMessage>
     {
         new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
     };

     Console.WriteLine("\n🔍 Researching...\n");

     try
     {
         var response = await agent.RunAsync(messages);

         foreach (var msg in response.Messages)
         {
             if (msg.Role == ChatRole.Assistant && msg.Text is { Length: > 0 })
             {
                 Console.WriteLine(msg.Text);
             }
         }
     }
     catch (Exception ex)
     {
         Console.WriteLine($"❌ Error: {ex.Message}");
     }

     Console.WriteLine();
 }

 Console.WriteLine("Goodbye!");

