 /// <summary>
 /// Provides web search and note-taking tools for the research agent.
 /// </summary>
 sealed class ResearchTools
 {
     private readonly List<string> _notes = [];
     private readonly HttpClient _http = new() { Timeout = TimeSpan.FromSeconds(15) };

     [Description("Search the web for information on a query. Returns a summary of search results.")]
     public async Task<string> SearchWeb(
         [Description("The search query to look up on the web.")] string query)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         try
         {
             // Use Wikipedia's API for real, free, no-key-required search
             var encoded = WebUtility.UrlEncode(query);
             var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=4&format=json&utf8=1";

             var json = await _http.GetStringAsync(url);

             // Also grab a short extract for the top result
             var extractUrl = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=4&format=json&utf8=1&srprop=snippet|titlesnippet";

             return $"Search results for \"{query}\":\n{json}";
         }
         catch (Exception ex)
         {
             return $"Search failed for \"{query}\": {ex.Message}";
         }
     }

     [Description("Save a research note. Use this to record important findings during research.")]
     public string SaveNote(
         [Description("The note content to save.")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
         return $"Note saved. You now have {_notes.Count} note(s).";
     }

     [Description("Retrieve all saved research notes to review findings before writing a summary.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         Console.WriteLine($"  📋 Reviewing {_notes.Count} note(s)");

         return string.Join("\n\n", _notes.Select((n, i) => $"[Note {i + 1}] {n}"));
     }

     public void ClearNotes() => _notes.Clear();
 }
